window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-54abcedd591ba696"]={"versions": [{"id": "FIG-54abcedd591ba696", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt aus dem AUTOSAR-Kontext „Interaction with Behavioral Models“. Das Diagramm modelliert die strukturelle Verknüpfung zwischen softwareseitigen Sensor-/Aktortypen (<code>SensorActuatorSoftwareComponentType</code>) und ihrer hardwareseitigen Repräsentation (<code>SensorActuatorHW</code>) sowie den Bezug zum Verhaltensmodellierungs-Paket <code>BM Software-Component</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Components::SensorActuatorSoftwareComponentType</code></strong>: Spezialisierung bzw. Ausprägung von <code>AtomicSoftwareComponentType</code>.\n</li><li><strong><code>Sensor Actuator::SensorActuatorHW</code></strong>: Spezialisierung bzw. Ausprägung von <code>HWElement</code>.\n</li><li><strong><code>BM Software-Component</code> (from Behavior Modeling)</strong>: Paket bzw. Modul der Verhaltensmodellierung, welches über eine gestrichelte Abhängigkeits-/Importbeziehung mit Stereotyp <code>«import»</code> auf <code>SensorActuatorSoftwareComponentType</code> referenziert.\n</li><li><strong>Assoziation <code>sensorActuator</code></strong>: Gerichtete Assoziation von <code>SensorActuatorSoftwareComponentType</code> auf <code>SensorActuatorHW</code> mit der Rollenbezeichnung <code>+sensorActuator</code> am Ziel und Kardinalitäten <code>1</code> (an der Quelle) zu <code>1</code> (am Ziel).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzabläufe. Die gerichtete Assoziation drückt eine feste 1:1-Zuordnung zwischen einer Sensor/Aktor-Software-Komponente und dem entsprechenden Hardware-Element aus. Der Import-Pfeil spezifiziert, dass Verhaltensmodelle innerhalb von <code>BM Software-Component</code> Zugriff auf die Typdefinition von <code>SensorActuatorSoftwareComponentType</code> nehmen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von Verhaltensmodellen und AUTOSAR-Architekturmodellen müssen beachten, dass jeder <code>SensorActuatorSoftwareComponentType</code> genau einem physischen <code>SensorActuatorHW</code>-Element zugewiesen ist (Multiplizität 1..1). Das Modellpaket <code>BM Software-Component</code> importiert diese Komponentendefinition, um sensorspezifische oder aktorspezifische Ein-/Ausgangscharakteristika und physikalische Verhaltensweisen simulativ und modellbasiert abbilden zu können.</p>"}, {"id": "FIG-0efda119d2ee5b6a", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt aus dem AUTOSAR-Kontext „Interaction with Behavioral Models“. Das Diagramm modelliert die strukturelle Verknüpfung zwischen softwareseitigen Sensor-/Aktortypen (<code>SensorActuatorSoftwareComponentType</code>) und ihrer hardwareseitigen Repräsentation (<code>SensorActuatorHW</code>) sowie den Bezug zum Verhaltensmodellierungs-Paket <code>BM Software-Component</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Components::SensorActuatorSoftwareComponentType</code></strong>: Spezialisierung bzw. Ausprägung von <code>AtomicSoftwareComponentType</code>.\n</li><li><strong><code>Sensor Actuator::SensorActuatorHW</code></strong>: Spezialisierung bzw. Ausprägung von <code>HWElement</code>.\n</li><li><strong><code>BM Software-Component</code> (from Behavior Modeling)</strong>: Paket bzw. Modul der Verhaltensmodellierung, welches über eine gestrichelte Abhängigkeits-/Importbeziehung mit Stereotyp <code>«import»</code> auf <code>SensorActuatorSoftwareComponentType</code> referenziert.\n</li><li><strong>Assoziation <code>sensorActuator</code></strong>: Gerichtete Assoziation von <code>SensorActuatorSoftwareComponentType</code> auf <code>SensorActuatorHW</code> mit der Rollenbezeichnung <code>+sensorActuator</code> am Ziel und Kardinalitäten <code>1</code> (an der Quelle) zu <code>1</code> (am Ziel).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzabläufe. Die gerichtete Assoziation drückt eine feste 1:1-Zuordnung zwischen einer Sensor/Aktor-Software-Komponente und dem entsprechenden Hardware-Element aus. Der Import-Pfeil spezifiziert, dass Verhaltensmodelle innerhalb von <code>BM Software-Component</code> Zugriff auf die Typdefinition von <code>SensorActuatorSoftwareComponentType</code> nehmen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von Verhaltensmodellen und AUTOSAR-Architekturmodellen müssen beachten, dass jeder <code>SensorActuatorSoftwareComponentType</code> genau einem physischen <code>SensorActuatorHW</code>-Element zugewiesen ist (Multiplizität 1..1). Das Modellpaket <code>BM Software-Component</code> importiert diese Komponentendefinition, um sensorspezifische oder aktorspezifische Ein-/Ausgangscharakteristika und physikalische Verhaltensweisen simulativ und modellbasiert abbilden zu können.</p>"}], "trans": [{"from": "FIG-54abcedd591ba696", "to": "FIG-0efda119d2ee5b6a", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
